// Normalize: clean phone, extract tenant_id and qualificação fields
const telefone = String($json.telefone || '').replace(/\D/g, '')
const tenant_id = $json.tenant_id || ''
const sessionId = $json.sessionId || $json.session_id || ''
const messageType = $json.messageType || $json.message_type || 'text'

return [{
  json: {
    ...$json,
    telefone_limpo: telefone,
    tenant_id,
    sessionId,
    messageType
  }
}]

// $json = array from Supabase GET: [] if new lead, [{...}] if found
// input = original qualificação data from webhook (via Normalize)
const input = $('Normalize').first().json
const existingLead = Array.isArray($json) && $json.length > 0 ? $json[0] : null
const telefone = input.telefone_limpo

// Preserve ALL previous metadata — never overwrite, only merge
const antigo = existingLead ? (existingLead.metadata || {}) : {}

// New qualification fields from this agent call
const novo = {
  objetivo: input.objetivo,
  faixa_valor: input.faixa_valor,
  bairro_interesse: input.bairro,
  interesse_principal: input.interesse,
  finalidade: input.finalidade,
  origem: input.origem,
  localizacao_visita: input.localizacao_visita,
  session_id: input.sessionId,
  message_type: input.messageType
}

// Strip undefined/null/empty so we don't overwrite with blanks
Object.keys(novo).forEach(k => {
  if (novo[k] === undefined || novo[k] === null || novo[k] === '') {
    delete novo[k]
  }
})

return [{
  json: {
    tenant_id: input.tenant_id,
    phone: telefone,
    name: existingLead ? existingLead.name : (input.nome || input.name || telefone),
    metadata: { ...antigo, ...novo }
  }
}]
